def is_same_letter_sequence(word1, word2):
    # 将字符串转换为字典
    word1_dict = {}
    for char in word1:
        word1_dict[char] = True
    word2_dict = {}
    for char in word2:
        word2_dict[char] = True
    # 遍历字典
    for char1, char2 in word1_dict.items():
        if char1 != char2:
            return False
    # 遍历字典
    for char1, char2 in word2_dict.items():
        if char1 != char2:
            return False
    return True
