def is_secure_password(password):
    # 检查密码是否包含字母和数字
    if not any(char.isalpha() or char.isdigit() for char in password):
        return False

    # 检查密码是否满足8位的长度
    if len(password) < 8:
        return False

    # 检查密码是否包含字母和数字
    for char in password:
        if not char.isalpha() or not char.isdigit():
            return False

    return True
